tem.isMajorNegative)\n    || majorKeywords.some(keyword => text.includes(keyword));\n  return {\n    score: ((sectorMatch || symbolMatch) ? 220 : 0) + (symbolMatch ? 65 : 0) + (majorSignal ? 100 : 0),\n    bucket: (sectorMatch || symbolMatch) ? ''watchlist_sector'' : (majorSignal ? ''major_market'' : ''other''),\n    reason: (sectorMatch || symbolMatch) ? ''命中自选股行业板块或标的'' : (majorSignal ? ''命中社会性重大利好/利空或高影响事件'' : ''其他公开信息''),\n    matched_topics: [\n      ...new Set([\n        ...sectorTokens.filter(tag => [tag, ...(sectorAliases[tag] || [])].some(term => text.includes(term))),\n        ...symbolTokens.filter(tag => text.includes(tag) || compactText.includes(compact(tag))),\n        ...majorKeywords.filter(keyword => text.includes(keyword))\n      ])\n    ]\n  };\n}", "updated_at": "", "updated_by": "admin", "source_prompt": ""}}, {"id": "tenant_lisa", "slug": "lisa", "name": "Lisa 港股研究社", "short_name": "Lisa 研究社", "logo_mark": "💎", "logo_url": "", "advisor": "投资女神Lisa", "tier": "专业租户", "focus": "港股互联网 · 南向资金 · 价值框架", "rights": "港股专栏 · 直播纪要 · Hermes 摘要 · 问答私域", "description": "面向港股互联网与价值投资粉丝的独立租户空间。", "portal_headline": "先把港股核心主线、代表性复盘和价值框架讲清楚，再把粉丝带进后续互动。", "portal_description": "这个门户面向粉丝展示 Lisa 的研究方向、最近复盘、代表性样本和互动权益，让用户先理解你在看什么、怎么判断，再进入 H5 跟踪和提问。", "dashboard_title": "Lisa 租户价值跟踪台", "dashboard_description": "突出港股估值、南向资金、回购与财报验证等核心经营与研究指标。", "knowledge_hub_config": {"items": [], "summary": "知识库尚未初始化。完成新的知识库设计后，再从管理端录入知识源。"}, "review_snapshots": [], "news_aggregation_algorithm": {"version": "v3", "strategy": "watchlist_sector_first", "script_js": "function rankNews(input) {\n  const normalize = (value) => String(value || '''').replace(/[\\s\\u3000·•/|_|-]+/g, '' '').trim();\n  const compact = (value) => String(value || '''').replace(/[\\s\\u3000·•/|_|-.]/g, '''').trim();\n  const tags = Array.isArray(input.item.tags) ? input.item.tags.map(normalize).filter(Boolean) : [];\n  const text = normalize([input.item.title, input.item.content, input.item.summary].filter(Boole